import CurrentLiquidityChart from '@/components/chart/dlmmChart/CurrentLiquidityChart'
import FunnelPrice from '@/components/common/FunnelPrice'
import ActionButton from '@/components/liquidity/common/ActionButton'
import { Legend } from '@/components/pools/createPool/depositAmount/DLMMDepositAmount'
import useDlmmPoolLiquidityDistribution from '@/hooks/dlmm/useDlmmPoolLiquidityDistribution'
import useGetDlmmPoolRelatedData from '@/hooks/dlmm/useGetDlmmPoolRelatedData'
import useDlmmLiquidityStore from '@/store/dlmm'
import { formatPrice } from '@cetus/utils'
import { Center, Heading, HStack, Spinner, VStack } from '@chakra-ui/react'
import { useState } from 'react'
function PoolLiquidityDistribution() {
  const { currentPrice, dlmmApiPoolInfo } = useDlmmLiquidityStore()
  const { getPerText } = useGetDlmmPoolRelatedData()
  const [maxBinsLength, setMaxBinsLength] = useState(141)
  const { activeBin, maxBinRangeData, allBinsLength, isLoading } = useDlmmPoolLiquidityDistribution(maxBinsLength)

  const handleAdd = () => {
    setMaxBinsLength(pre => pre - 8)
  }

  const handleSub = () => {
    setMaxBinsLength(pre => pre + 8)
  }

  return (
    <VStack w="100%" gap={{ base: '20px', lg: '40px' }} p="20px" borderRadius="16px" border="1px solid" borderColor="border" bg="bg_secondary">
      <VStack gap="20px" w="100%">
        <HStack w="100%" justify="space-between">
          <Heading fontSize="16px" fontWeight="400">
            Pool Liquidity Distribution
          </Heading>
          <HStack gap="40px">
            <HStack gap="16px">
              <FunnelPrice price={formatPrice(currentPrice)} perText={getPerText(true)} />
              <Legend symbol={dlmmApiPoolInfo?.displayTokenA?.symbol || ''} color="dlmm_blue" />
              <Legend symbol={dlmmApiPoolInfo?.displayTokenB?.symbol || ''} color="dlmm_green" />
            </HStack>
            <HStack>
              <ActionButton type="Add" onClick={handleAdd} disabled={maxBinsLength <= 21} />
              <ActionButton type="Sub" onClick={handleSub} disabled={maxBinsLength >= Math.min(allBinsLength, 501)} />
            </HStack>
          </HStack>
        </HStack>
        {activeBin !== undefined &&
          (isLoading ? (
            <Center h="160px">
              <Spinner />
            </Center>
          ) : (
            <CurrentLiquidityChart type="simulation" data={maxBinRangeData} activeBin={Number(activeBin)} width={1118} height={160} />
          ))}
      </VStack>
    </VStack>
  )
}

export default PoolLiquidityDistribution
