import useDlmmLiquidityStore from '@/store/dlmm'
import useAddDlmmLiquidityStore, { RangePriceType } from '@/store/dlmm/addDlmmLiquidity'
import { getRelatedDisplayPrice } from '@/utils/dlmm'
import { d } from '@cetus/utils'
import { BinUtils, MIN_BIN_ID } from 'dd_dlmm_sdk'
import { PriceDataType } from '../create-pool/useCreateDLMMPool'
import useCreatePriceBin from './useCreatePriceBin'

function useDlmmPriceRange() {
  const { handleActionBinPrice } = useCreatePriceBin()
  const { currentBinStep, dlmmApiPoolInfo } = useDlmmLiquidityStore()
  const { minPriceData, maxPriceData, setMinPriceData, setMaxPriceData, fromToken, toToken } = useAddDlmmLiquidityStore()

  const getReverseType = (type: 'Add' | 'Sub') => {
    if (type === 'Add') {
      return 'Sub'
    }
    return 'Add'
  }
  const handlePriceAction = (type: 'Add' | 'Sub', price: PriceDataType) => {
    const { bin_id, price: _price } = handleActionBinPrice(
      price,
      currentBinStep!,
      dlmmApiPoolInfo?.tokenA?.decimals,
      dlmmApiPoolInfo?.tokenB?.decimals,
      type
    )
    const [displayPrice, reversePrice, displayReversePrice] = getRelatedDisplayPrice(_price)

    if (price?.type === 'lower') {
      setMinPriceData({
        tokenA: dlmmApiPoolInfo!.tokenA,
        tokenB: dlmmApiPoolInfo!.tokenB,
        binId: bin_id,
        price: _price,
        displayPrice,
        reversePrice,
        displayReversePrice,
        type: 'lower'
      })
    } else {
      setMaxPriceData({
        tokenA: dlmmApiPoolInfo!.tokenA,
        tokenB: dlmmApiPoolInfo!.tokenB,
        binId: bin_id,
        price: _price,
        displayPrice,
        reversePrice,
        displayReversePrice,
        type: 'upper'
      })
    }
  }
  const handleAddPrice = (price: PriceDataType) => {
    handlePriceAction('Add', price)
  }

  const handleSubPrice = (price: PriceDataType) => {
    handlePriceAction('Sub', price)
  }

  // 失去焦点操作
  const onPriceChange = (data: RangePriceType, value: string) => {
    const tokenA = data.tokenA
    const tokenB = data.tokenB
    if (!tokenA || !tokenB) return
    let _binId
    if (d(value).lte('0')) {
      _binId = MIN_BIN_ID
    } else {
      _binId = BinUtils.getBinIdFromPrice(value, currentBinStep!, false, tokenA?.decimals, tokenB?.decimals)
    }
    const [displayPrice, reversePrice, displayReversePrice] = getRelatedDisplayPrice(value)
    const res = {
      tokenA,
      tokenB,
      binId: _binId,
      price: value,
      displayPrice: value,
      reversePrice,
      displayReversePrice,
      type: data?.type
    }

    if (data?.type === 'lower') {
      setMinPriceData(res)
    } else {
      setMaxPriceData(res)
    }
  }

  return { handleAddPrice, handleSubPrice, onPriceChange }
}

export default useDlmmPriceRange
