import FunnelPrice from '@/components/common/FunnelPrice'
import { Legend } from '@/components/pools/createPool/depositAmount/DLMMDepositAmount'
import { PriceDataType } from '@/hooks/create-pool/useCreateDLMMPool'
import useDlmmAddLiquidityChart from '@/hooks/dlmm/useDlmmAddLiquidityChart'
import useGetDlmmContractPoolInfo from '@/hooks/dlmm/useGetDlmmContractPoolInfo'
import useGetDlmmPoolRelatedData from '@/hooks/dlmm/useGetDlmmPoolRelatedData'
import useInitDlmmPoolPriceRange from '@/hooks/dlmm/useInitDlmmPoolPriceRange'
import useDlmmLiquidityStore from '@/store/dlmm'
import useAddDlmmLiquidityStore from '@/store/dlmm/addDlmmLiquidity'
import { getRelatedDisplayPrice } from '@/utils/dlmm'
import { getReversePrice } from '@/utils/pool'
import { SelectTab } from '@cetus/design'
import { Tab } from '@cetus/design/src/components/common/SelectTab'
import useQueryParams from '@cetus/hooks/src/useQueryParams'
import { Icon } from '@cetus/ui-kit'
import { d, formatPrice, isAvailableObject } from '@cetus/utils'
import { Center, Divider, HStack, Skeleton, Text, VStack } from '@chakra-ui/react'
import { BinUtils } from 'dd_dlmm_sdk'
import DivisionBlock from '../common/DivisionBlock'
import ControlPriceRange from './ControlPriceRange'
import NumBins from './NumBins'
import PriceRangeForDate from './PriceRangeForDate'
import DlmmRangeChart from './RangeChart'

type SetPriceRangeProps = {
  perText: string
  direct: boolean
  minPriceData: PriceDataType | null
  maxPriceData: PriceDataType | null
  rangeTabList: any[]
  currentRangeTab?: string
  onReverseClick: (item?: Tab) => void
}
function SetPriceRange({ perText, direct, minPriceData, maxPriceData, rangeTabList, currentRangeTab, onReverseClick }: SetPriceRangeProps) {
  const { currentPrice, dlmmApiPoolInfo, dlmmContractPoolInfo } = useDlmmLiquidityStore()
  const { getPerText } = useGetDlmmPoolRelatedData()
  const { numBins, positionCount, fromToken, toToken, setNumBins, setMaxPriceData } = useAddDlmmLiquidityStore()
  const { getDlmmContractPoolInfo } = useGetDlmmContractPoolInfo()
  const { handleInitPriceRange } = useInitDlmmPoolPriceRange()
  const { currentLiquidityBins, activeId, maxBinRangeData, handleRangeChange } = useDlmmAddLiquidityChart(direct)
  const { poolId } = useQueryParams()
  const handleReset = async () => {
    const res = await getDlmmContractPoolInfo(poolId)
    if (res && isAvailableObject(res)) {
      const _currentPrice = BinUtils?.getPriceFromBinId(
        res?.active_id,
        res?.bin_step,
        dlmmApiPoolInfo?.tokenA?.decimals,
        dlmmApiPoolInfo?.tokenB?.decimals
      )

      handleInitPriceRange(res, _currentPrice)
    }
  }

  const handleNumBinsBlur = () => {
    const binId = d(minPriceData?.binId).plus(numBins).minus(1).toNumber()
    const price = BinUtils.getPriceFromBinId(
      binId,
      dlmmContractPoolInfo!.binStep,
      dlmmApiPoolInfo?.tokenA?.decimals,
      dlmmApiPoolInfo?.tokenB?.decimals
    )
    const [displayPrice, reversePrice, displayReversePrice] = getRelatedDisplayPrice(price)

    setMaxPriceData({
      tokenA: dlmmApiPoolInfo!.tokenA,
      tokenB: dlmmApiPoolInfo!.tokenB,
      binId,
      price,
      displayPrice,
      reversePrice,
      displayReversePrice,
      type: 'upper'
    })
  }

  const handleNumBinsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const input = event.target.value
    if (input === '--') {
      setNumBins(input)
      return
    }
    if (/^[1-9][0-9]*$/.test(input)) {
      setNumBins(input)
      return
    }
  }

  return (
    <DivisionBlock
      title={
        <HStack h="20px" gap="12px">
          <Text lineHeight="20px" fontSize="16px" fontWeight="500" color="text_caption">
            Set Price Range
          </Text>
          <HStack
            as="button"
            gap="2px"
            _hover={{ p: { color: 'text_caption' }, svg: { fill: 'text_caption' } }}
            cursor="pointer"
            onClick={handleReset}
          >
            <Icon xlinkHref="#icon-reset" fontSize="14px" />
            <Text fontSize="12px">Reset Price</Text>
          </HStack>
        </HStack>
      }
      wrapStyle={{ w: '100%', gap: '20px', className: 'dlmm-tutorial-step-5' }}
    >
      <HStack>
        {!rangeTabList || !rangeTabList.length ? (
          <Skeleton h="32px" borderRadius="8px" w="180px" />
        ) : (
          <HStack gap="20px">
            <HStack gap="12px">
              <Legend symbol={dlmmApiPoolInfo?.displayTokenA?.symbol || ''} color="dlmm_blue" />
              <Legend symbol={dlmmApiPoolInfo?.displayTokenB?.symbol || ''} color="dlmm_green" />
            </HStack>
            <SelectTab<any, any>
              type="outlineTab"
              tabList={rangeTabList}
              currentTab={currentRangeTab}
              handleChangeTab={tab => onReverseClick(tab)}
              wrapStyle={{
                h: '32px',
                p: '3px',
                border: '1px solid',
                borderColor: 'border',
                borderRadius: '8px',
                gap: '4px',
                zIndex: '99'
              }}
              itemStyle={{
                h: '24px',
                p: '4px 12px',
                borderRadius: '4px',
                gap: '4px'
              }}
            />
          </HStack>
        )}
      </HStack>

      <VStack w="100%" gap="16px">
        <VStack w="100%" gap="12px">
          <HStack w="100%" justify="center">
            <FunnelPrice price={formatPrice(direct ? currentPrice : getReversePrice(currentPrice))} perText={getPerText(true)} showIcon={false} />
          </HStack>
          <DlmmRangeChart
            direct={direct}
            currentLiquidityBins={currentLiquidityBins}
            activeId={activeId}
            maxBinRangeData={maxBinRangeData}
            handleRangeChange={handleRangeChange}
          />
        </VStack>

        <HStack>
          <ControlPriceRange
            perText={getPerText(true)}
            direct={direct}
            lowerPrice={direct ? minPriceData : maxPriceData}
            upperPrice={direct ? maxPriceData : minPriceData}
            wrapStyle={{ gap: '8px' }}
          />
          <NumBins
            isLoading={false}
            numBins={numBins}
            positionCount={positionCount}
            onNumBinsBlur={handleNumBinsBlur}
            onNumBinsChange={handleNumBinsChange}
          />
        </HStack>
        {d(positionCount).gt(1) && (
          <Center p="8px" w="100%" bg="primary_opacity.10" borderRadius="8px">
            <Text color="primary" fontSize="12px" h="16px" fontWeight="400">
              SUI needs to created {positionCount} Positions
            </Text>
          </Center>
        )}
        {minPriceData && maxPriceData && d(minPriceData?.binId).gt(maxPriceData?.binId) && (
          <Center p="8px" w="100%" bg="primary_red_opacity.10" borderRadius="8px">
            <Text color="primary_red" fontSize="12px" h="16px" fontWeight="400">
              The Max price should be higher than or equal to the Min price
            </Text>
          </Center>
        )}
        <Divider w="100%" orientation="horizontal" />

        <PriceRangeForDate direct={direct} currentLiquidityBins={currentLiquidityBins} maxBinRangeData={maxBinRangeData} />
      </VStack>
    </DivisionBlock>
  )
}

export default SetPriceRange
