import Slippage from '@/components/common/Slippage'
import PoolsAnalytics from '@/components/liquidity/dlmm/analytics/PoolsAnalytics'
import DLMMDeposit from '@/components/liquidity/dlmm/deposit'
import MyPositions from '@/components/liquidity/dlmm/MyPositions'
import PoolsStats from '@/components/liquidity/dlmm/PoolsStats'
import SelectTokenAnddFeeConfirm from '@/components/liquidity/dlmm/SelectTokenAndFeeConfirm'
import { SelectToken } from '@/components/selectPool/SelectToken'
import useDlmmLiquidity from '@/hooks/dlmm/useDlmmLiquidity'
import useGetDlmmTvlInfo from '@/hooks/dlmm/useGetDlmmTvlInfo'
import useDlmmLiquidityStore from '@/store/dlmm'
import { isTrustedToken } from '@/utils'
import { CetusTooltip, CurrentPrice, FeeSelectBlock, SelectTab } from '@cetus/design'
import WarningTokenTipsModal from '@cetus/design/src/components/common/WarningTokenTipModal'
import useQueryParams from '@cetus/hooks/src/useQueryParams'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Token } from '@cetus/types'
import { BackButton, Icon, NoData, RefreshButton } from '@cetus/ui-kit'
import { formatNumberWithDown } from '@cetus/utils'
import { Box, Button, Center, HStack, Spinner, Stack, Text, useDisclosure, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { TabsEnum } from '../hooks/clmm/useLiquidityInteraction'

function Dlmm() {
  const navigate = useNavigate()
  const { poolId, from, to } = useQueryParams()

  const { dlmmApiPoolInfoLoading, currentPrice, reverseCurrentPrice } = useDlmmLiquidityStore()

  const {
    dlmmApiPoolInfo,
    selectedTokenA,
    selectedTokenB,
    setCurrentBinStep,
    currentBinStep,
    currentTab,
    setCurrentTab,
    tabList,
    favoriteStyle,
    onChangeFavorites,
    setSelectedTokenA,
    setSelectedTokenB,
    onConfirm,
    refreshMarketPrice,
    onJump2Swap,
    handleSelectToken,
    getSelectTokenProps,
    rangeTabList,
    quoteWhiteTokenList,
    onBinStepChange,
    baseFeeList,
    currentBaseFee,
    baseFee,
    setBaseFee,
    handleRefresh,
    handleGetPrice
  } = useDlmmLiquidity()

  const { isApp } = useWindowWidth()

  const { isOpen, onOpen, onClose } = useDisclosure()

  const { totalAmountUSD: totalTvl, tvlLoading } = useGetDlmmTvlInfo()
  const showContent = poolId && dlmmApiPoolInfo?.tokenA?.coinType && dlmmApiPoolInfo?.tokenB?.coinType

  const { tooltip, xlinkHref, svgFill, svgHover } = favoriteStyle

  const [selectTokenAProps, setSelectTokenAProps] = useState<any>({})
  const [selectTokenBProps, setSelectTokenBProps] = useState<any>({})
  const [priceDirect, setPriceDirect] = useState(true)
  const fetchSelectTokenProps = async () => {
    try {
      const tokenAProps = await getSelectTokenProps(from, selectedTokenA)
      const tokenBProps = await getSelectTokenProps(to, selectedTokenB)
      setSelectTokenAProps(tokenAProps)
      setSelectTokenBProps(tokenBProps)
    } catch (error) {
      console.log(error, 'fetchSelectTokenProps')
    }
  }
  useEffect(() => {
    fetchSelectTokenProps()
  }, [from, to, selectedTokenA, selectedTokenB])

  return (
    <>
      <Box w="100%" mt="20px">
        <HStack w="100%" minW={{ base: '100%', lg: '1024px' }} justify="space-between">
          <BackButton text="Pools" onClick={() => navigate('/pools?tab=dlmm_pools')} />
          {showContent && (
            <HStack gap="8px">
              <CetusTooltip placement="top" tooltip={tooltip}>
                <Button
                  variant="outline"
                  w="32px"
                  h="32px"
                  lineHeight="32px"
                  onClick={onChangeFavorites}
                  p="0 6px"
                  borderRadius="8px"
                  color="text_paragraph"
                  bg="background"
                  display="flex"
                  justifyContent="center"
                  gap="4px"
                  sx={{
                    _hover: {
                      color: 'text_caption',
                      svg: {
                        fill: svgHover
                      }
                    }
                  }}
                >
                  <Icon xlinkHref={xlinkHref} svgFill={svgFill} svgHover={svgHover} fontSize="18px" />
                </Button>
              </CetusTooltip>
              <CetusTooltip placement="top" tooltip="Trade">
                <Button
                  variant="outline"
                  bg="background"
                  h="32px"
                  w="32px"
                  onClick={onJump2Swap}
                  borderRadius="8px"
                  p="0 6px"
                  color="text_paragraph"
                  display="flex"
                  justifyContent="center"
                  gap="4px"
                  sx={{
                    _hover: {
                      color: 'text_caption',
                      svg: {
                        fill: 'text_caption'
                      }
                    }
                  }}
                >
                  <Icon xlinkHref="#icon-icon_swap1" fontSize="16px" />
                </Button>
              </CetusTooltip>
              <CetusTooltip placement="top" tooltip="Refresh">
                <Box>
                  <RefreshButton
                    key={poolId}
                    handleRefresh={handleRefresh}
                    isAutoRefresh
                    refreshInterval={60}
                    innerStyle={{ bg: 'background' }}
                    w="32px"
                    h="32px"
                    borderRadius="8px"
                    bg="background"
                  />
                </Box>
              </CetusTooltip>
            </HStack>
          )}
        </HStack>
        <Stack
          flexDir={{ base: 'column', lg: 'row' }}
          w="100%"
          minW={{ base: '100%', lg: '1024px' }}
          justify="space-between"
          mt="20px"
          gap={{ base: '20px', lg: '8px' }}
        >
          <Stack flexDir={{ base: 'column', lg: 'row' }} gap={{ base: '20px', lg: '8px' }} align={{ base: 'flex-start', lg: 'center' }}>
            <HStack gap="12px">
              <SelectToken
                onChange={token => {
                  handleSelectToken(token, selectedTokenA, selectedTokenB, from, to, true)
                }}
                {...selectTokenAProps}
              />
              <SelectToken
                onChange={token => {
                  handleSelectToken(token, selectedTokenB, selectedTokenA, to, from, false)
                }}
                {...selectTokenBProps}
              />
            </HStack>
            <FeeSelectBlock<'dlmm'>
              poolType="dlmm"
              value={currentBaseFee}
              loading={!currentBaseFee || dlmmApiPoolInfoLoading}
              onChange={item => {
                if (item?.poolAddress) {
                  navigate(`/dlmm?poolId=${item?.poolAddress}`)
                } else {
                  setBaseFee(item)
                  onOpen()
                }
              }}
              options={baseFeeList}
            />
          </Stack>
          {showContent && (
            <PoolsStats apiPoolInfo={dlmmApiPoolInfo} totalTvl={totalTvl} apiPoolInfoLoading={dlmmApiPoolInfoLoading} tvlLoading={tvlLoading} />
          )}
        </Stack>
        {showContent ? (
          <>
            <Stack
              w="100%"
              flexDir={{ base: 'column', lg: 'row' }}
              justify={{ base: 'center', lg: 'space-between' }}
              align={{ base: 'flex-start', lg: 'center' }}
              minW={{ base: '100%', lg: '1024px' }}
            >
              <SelectTab<any, any>
                type="borderTab"
                tabList={tabList}
                currentTab={currentTab}
                handleChangeTab={item => {
                  const key = Object.keys(TabsEnum).find(tab => TabsEnum[tab as keyof typeof TabsEnum] === item.label)
                  if (poolId) {
                    navigate(`/dlmm?tab=${key}&poolId=${poolId}`)
                  }
                  setCurrentTab(key as keyof typeof TabsEnum)
                }}
                wrapStyle={{
                  w: { base: '100%', lg: 'auto' },
                  justify: { base: 'space-between', lg: 'flex-start' },
                  p: { base: '0 12px', lg: '0' },
                  bg: { base: 'bg_secondary', lg: 'transparent' },
                  h: isApp ? '60px' : '58px',
                  gap: { base: '8px', lg: '45px' },
                  border: { base: '1px solid', lg: 'none' },
                  borderColor: { base: 'border', lg: 'transparent' },
                  borderRadius: { base: '16px', lg: 'unset' },
                  mt: { base: '20px', lg: '12px' }
                }}
                itemStyle={{
                  fontSize: isApp ? '14px' : '16px',
                  fontWeight: '500'
                }}
              />
              <HStack>
                {currentTab !== 'deposit' && dlmmApiPoolInfo && (
                  <Stack
                    w={isApp ? '100%' : 'auto'}
                    mt={{ base: '4px', lg: '12px' }}
                    gap="12px"
                    flexDir={{ base: 'column', lg: 'row' }}
                    justify={{ base: 'center', lg: 'space-between' }}
                    align={{ base: 'flex-start', lg: 'center' }}
                  >
                    <Text>Current Price</Text>
                    <CurrentPrice
                      noCenter={isApp ? true : false}
                      fromToken={dlmmApiPoolInfo?.displayTokenA}
                      toToken={dlmmApiPoolInfo?.displayTokenB}
                      fromValue="1"
                      toValue={formatNumberWithDown(dlmmApiPoolInfo?.isReverse ? reverseCurrentPrice : currentPrice, 6, true).toString()}
                      color="text_caption"
                      wrapStyle={isApp ? { w: '100%' } : {}}
                      handlePageToggleDirect={() => setPriceDirect(!priceDirect)}
                    />
                  </Stack>
                )}
                {currentTab === 'deposit' && (
                  <Box mt={{ base: '4px', lg: '12px' }}>
                    <Slippage slippageType="liquidity" />
                  </Box>
                )}
              </HStack>
            </Stack>

            <Box h={{ base: '20px', lg: '8px' }} />
            {currentTab === 'deposit' && (
              <DLMMDeposit
                rangeTabList={rangeTabList as any}
                getList={handleRefresh}
                getPrice={handleGetPrice}
                binStep={dlmmApiPoolInfo?.bin_step}
                baseFee={dlmmApiPoolInfo?.base_fee_rate}
              />
            )}
            {currentTab === 'positions' && <MyPositions priceDirect={priceDirect} />}
            {currentTab === 'analytics' && <PoolsAnalytics />}
          </>
        ) : (
          <Box mt="20px">
            {!dlmmApiPoolInfo && dlmmApiPoolInfoLoading ? (
              <Center w="100%" h="480px" background="bg_secondary" borderRadius="12px" border="1px solid" borderColor="border">
                <Spinner />
              </Center>
            ) : (
              <NoData type="custom" imgUrl="/images/img_create_pool.png" h="480px">
                <VStack>
                  {selectedTokenA && selectedTokenB ? (
                    isTrustedToken(selectedTokenA, quoteWhiteTokenList) || isTrustedToken(selectedTokenB, quoteWhiteTokenList) ? (
                      <>
                        <Text h="20px" lineHeight="20px" fontSize="14px" color="text_caption" fontWeight="500">
                          This Pool has not been initialized
                        </Text>
                        <Text fontSize="14px">Do you want to initialize it?</Text>
                        <Button
                          mt="12px"
                          w="120px"
                          h="32px"
                          borderRadius="8px"
                          colorScheme="blue"
                          fontSize="14px"
                          fontWeight="500"
                          onClick={() => {
                            onClose()
                            onConfirm()
                          }}
                        >
                          Initialized Pool
                        </Button>
                      </>
                    ) : (
                      <Text h="20px" lineHeight="20px" fontSize="14px" color="text_caption">
                        No liquidity data
                      </Text>
                    )
                  ) : (
                    <Text h="20px" lineHeight="20px" fontSize="14px" color="text_caption">
                      Select the token you want to provide liquidity for.
                    </Text>
                  )}
                </VStack>
              </NoData>
            )}
          </Box>
        )}
      </Box>
      {/* Token 警告弹窗 */}
      {selectedTokenA && selectedTokenB && (
        <WarningTokenTipsModal
          tokensInfo={[selectedTokenA, selectedTokenB]}
          waringModalCancel={(tokenInfo: Token[]) => {
            navigate('/pools?tab=dlmm')
          }}
        />
      )}
      <SelectTokenAnddFeeConfirm
        title="This Pool has not been initialized"
        subTitle="Do you want to initialize it?"
        btnText="Initialized Pool"
        isOpen={isOpen}
        onClose={onClose}
        onConfirm={onConfirm}
      />
    </>
  )
}

export default Dlmm
