import WithTooltipInfo from '@/components/common/WithTooltipInfo'
import { Block, CetusTooltip } from '@cetus/design'
import { Input, Skeleton, Text, VStack } from '@chakra-ui/react'

type NumBinsProps = {
  numBins: number | string
  positionCount: number
  onNumBinsChange: (event: React.ChangeEvent<HTMLInputElement>) => void
  onNumBinsBlur: () => void
  isLoading?: boolean
}

function NumBins({ numBins, positionCount, onNumBinsBlur, onNumBinsChange, isLoading }: NumBinsProps) {
  return (
    <Block flex="0 0 148px" h="80px" borderRadius="12px" p="8px 12px 12px">
      <VStack w="100%">
        <WithTooltipInfo
          label="Num Bins"
          tooltip="Total price bins in this DLMM position."
          wrapStyle={{
            width: 'auto',
            flexDir: 'column',
            align: 'center',
            sx: {
              'div > p:first-of-type': {
                fontSize: '12px'
              }
            },
            gap: '4px'
          }}
          w="250px"
        >
          {isLoading ? (
            <Skeleton w="100px" h="14px" />
          ) : (
            <Input
              value={numBins}
              onChange={onNumBinsChange}
              style={{
                width: 'calc(100% - 8px)',
                background: 'none',
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                opacity: 1,
                outline: 'none',
                color: 'var(--chakra-colors-text_caption)',
                fontSize: '14px',
                height: '14px',
                lineHeight: '14px',
                textAlign: 'center',
                fontWeight: '500'
              }}
              onBlur={onNumBinsBlur}
            />
          )}
        </WithTooltipInfo>
        <CetusTooltip
          tooltip={
            <Text fontSize="12px" lineHeight="20px">
              Each position covers up to 69 bins.
            </Text>
          }
        >
          <Text fontSize="12px" color="primary_gray" cursor="pointer" textDecoration="underline dotted" textUnderlineOffset="2px">
            {`${positionCount} Positions`}
          </Text>
        </CetusTooltip>
      </VStack>
    </Block>
  )
}

export default NumBins
