import { EstimatedAprDateTypeList } from '@/components/common/EstimatedApr'
import { useDlmmApr } from '@/hooks/dlmm/useDlmmApr'
import useDlmmLiquidityStore from '@/store/dlmm'
import useDlmmDepositStore from '@/store/dlmm/dlmmDeposit'
import { CurrentBinChartData, MaxBinRangeChartData } from '@/types/dlmm'
import { CetusTooltip, SelectTab } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Icon } from '@cetus/ui-kit'
import { d, formatPrice, isAvailableObject } from '@cetus/utils'
import { HStack, StackProps, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

const dateTypeList = [
  {
    label: '24H',
    key: 'day'
  },
  {
    label: '7D',
    key: 'week'
  },
  {
    label: '30D',
    key: 'month'
  }
]

function PriceRangeForDate({
  direct,
  wrapStyle = {},
  currentLiquidityBins,
  maxBinRangeData
}: {
  direct: boolean
  wrapStyle?: StackProps
  currentLiquidityBins?: CurrentBinChartData
  maxBinRangeData?: MaxBinRangeChartData
}) {
  const { priceRangeMap } = useDlmmDepositStore()
  const [tab, setTab] = useState({ type: '30D', key: 'month' })
  const { minPriceForDate, maxPriceForDate, setMinPriceForDate, setMaxPriceForDate, dlmmApiPoolInfo } = useDlmmLiquidityStore()
  useEffect(() => {
    let _min = ''
    let _max = ''
    if (isAvailableObject(priceRangeMap) && isAvailableObject(tab)) {
      const lowest = (priceRangeMap as any)[tab?.type]?.[0]
      const lowValue = direct ? lowest : d(1).div(lowest).toString()
      const highest = (priceRangeMap as any)[tab?.type]?.[1]
      const highValue = direct ? highest : d(1).div(highest).toString()
      _min = formatPrice(lowValue, 6)
      _max = formatPrice(highValue, 6)
    } else {
      _min = '-'
      _max = '-'
    }
    setMinPriceForDate(_min)
    setMaxPriceForDate(_max)
  }, [direct, tab?.key, priceRangeMap])

  const { isApp } = useWindowWidth()

  const { estimateApr, loading: aprLoading } = useDlmmApr(maxBinRangeData?.list || [], currentLiquidityBins?.list || [], tab?.type, dlmmApiPoolInfo)
  const isEstimateApNaN = isNaN(estimateApr as any)

  return (
    <HStack w="100%" justify="center" gap="16px" justifyContent="space-between" {...wrapStyle}>
      <VStack align="flex-start">
        <HStack>
          <Text fontSize="14px" whiteSpace="nowrap">
            {tab?.type}&nbsp;Price Range
          </Text>
        </HStack>

        <Text color="text_caption" fontSize="14px" lineHeight="14px" h="14px">
          {direct ? minPriceForDate : maxPriceForDate}&nbsp;-&nbsp;
          {direct ? maxPriceForDate : minPriceForDate}
        </Text>
      </VStack>

      <VStack align="flex-start">
        <HStack>
          <CetusTooltip
            tooltip={
              <Text fontSize="12px" lineHeight="20px">
                APR based on the past 30D historical trade fees and emissions. Only positions in range earn yield. Past performance is not indicative
                of future results. Calculations are an estimate and only for reference.
              </Text>
            }
          >
            <HStack>
              <Text>Estimated APR</Text>
              <Icon xlinkHref="#icon-icon_tips" />
            </HStack>
          </CetusTooltip>
        </HStack>

        <Text
          color={isEstimateApNaN ? 'text_paragraph' : 'primary'}
          textDecoration={isEstimateApNaN ? 'none' : 'underline dotted'}
          textDecorationColor="primary"
        >
          {isEstimateApNaN ? '--' : `${estimateApr}%`}
        </Text>
      </VStack>
      <SelectTab<any, any>
        type="outlineTab"
        tabList={EstimatedAprDateTypeList}
        currentTab={tab}
        handleChangeTab={tab => {
          setTab({ type: tab.label, key: tab.key })
        }}
        isActive={(currentTab, tab) => currentTab.key === tab.key}
        wrapStyle={{
          h: isApp ? '28px' : '32px',
          p: '3px',
          border: '1px solid',
          borderColor: 'border',
          borderRadius: '8px',
          gap: '4px',
          w: 'auto'
        }}
        itemStyle={{
          h: '24px',
          p: '4px 8px',
          fontSize: '12px',
          borderRadius: '4px',
          flex: 1
        }}
      />
    </HStack>
  )
}

export default PriceRangeForDate
